@Bean
public OrderServiceV1 orderServiceV1(LogTrace trace, LogTraceAdvice advice) {
    OrderServiceV1 target = new OrderServiceV1Impl(orderRepositoryV1(trace));
    ProxyFactory factory = new ProxyFactory(target);
    factory.addAdvisor(new DefaultPointcutAdvisor(new NameMatchPointcut(), advice));
    return (OrderServiceV1) factory.getProxy();
}

