-- 무엇이 걸렸는지 물어본다

@GetMapping(value = "/pointcut/match", produces = "text/plain")
String match(String bean) {
    Object proxy = ctx.getBean(bean);
    Advised advised = (Advised) proxy;
    Class<?> target = advised.getTargetClass();
    var sb = new StringBuilder();
    for (Advisor a : advised.getAdvisors()) {
        if (!(a instanceof PointcutAdvisor pa)) continue;
        for (Method m : target.getMethods()) {
            if (m.getDeclaringClass() == Object.class) continue;
            boolean hit = pa.getPointcut().getClassFilter().matches(target)
                       && pa.getPointcut().getMethodMatcher().matches(m, target);
            sb.append(String.format("%-14s %s%n", m.getName(), hit ? "걸림" : "통과"));
        }
    }
    return sb.toString();
}

